    for (i = 0; i < (sizeof(struct BattleTowerEReaderTrainer) - 4) / 4; i++)  
        ereaderTrainer->checksum += ((u32 *)ereaderTrainer)[i];

ClearEReaderTrainer.body:
u32 i;

    for (i = 0; i < (sizeof(struct BattleTowerEReaderTrainer)) / 4; i++)
